pragma solidity 0.8.24;

import {IAori} from "./IAori.sol";

interface IAoriReader {
    function srcEidToFillerFills(
        uint32 srcEid,
        address filler,
        uint256 index
    ) external view returns (bytes32);
    function orders(
        bytes32 orderId
    )
        external
        view
        returns (
            uint128 inputAmount,
            uint128 outputAmount,
            address inputToken,
            address outputToken,
            uint32 startTime,
            uint32 endTime,
            uint32 srcEid,
            uint32 dstEid,
            address offerer,
            address recipient
        );
}

/**
 * @title AoriPeriphery
 * @notice A periphery contract that aggregates fill statistics per endpoint ID
 * @dev Provides view functions to get order counts and input token sums for fillers
 */
contract AoriPeriphery {
    /// @notice The Aori contract to read from
    IAoriReader public immutable aori;

    /// @notice Statistics for a filler on a specific source endpoint
    struct FillerStats {
        uint256 orderCount;
        uint256 totalInputAmount;
    }

    /// @notice Detailed statistics broken down by input token
    struct TokenStats {
        address inputToken;
        uint256 orderCount;
        uint256 totalInputAmount;
    }

    constructor(address _aori) {
        require(_aori != address(0), "Invalid Aori address");
        aori = IAoriReader(_aori);
    }

    /**
     * @notice Get all order hashes for a filler across multiple source endpoints
     * @param srcEids Array of source endpoint IDs to query
     * @param filler The filler address
     * @return orderHashesPerEid Array of order hash arrays, one per source endpoint
     */
    function getPendingSettle(
        uint32[] calldata srcEids,
        address filler
    ) external view returns (bytes32[][] memory orderHashesPerEid) {
        orderHashesPerEid = new bytes32[][](srcEids.length);

        for (uint256 j = 0; j < srcEids.length; j++) {
            bytes32[] memory temp = new bytes32[](100);
            uint256 count = 0;

            for (uint256 i = 0; i < 100; i++) {
                try aori.srcEidToFillerFills(srcEids[j], filler, i) returns (
                    bytes32 orderId
                ) {
                    temp[count++] = orderId;
                } catch {
                    break;
                }
            }

            // Copy to correctly sized array
            orderHashesPerEid[j] = new bytes32[](count);
            for (uint256 i = 0; i < count; i++) {
                orderHashesPerEid[j][i] = temp[i];
            }
        }
    }

    /**
     * @notice Get total input amounts grouped by input token for a list of order hashes
     * @param orderHashes Array of order hashes to query
     * @return inputTokens Array of unique input token addresses
     * @return totalAmounts Array of total input amounts corresponding to each token
     */
    function getOrdersInputTotals(
        bytes32[] calldata orderHashes
    )
        external
        view
        returns (address[] memory inputTokens, uint256[] memory totalAmounts)
    {
        // Use small fixed buffer - realistically won't have more than 20 unique tokens
        address[] memory tempTokens = new address[](20);
        uint256[] memory tempAmounts = new uint256[](20);
        uint256 uniqueCount = 0;

        for (uint256 i = 0; i < orderHashes.length; i++) {
            (uint128 inputAmount, , address inputToken, , , , , , , ) = aori
                .orders(orderHashes[i]);

            // Check if token already exists
            bool found = false;
            for (uint256 k = 0; k < uniqueCount; k++) {
                if (tempTokens[k] == inputToken) {
                    tempAmounts[k] += inputAmount;
                    found = true;
                    break;
                }
            }

            if (!found && uniqueCount < 20) {
                tempTokens[uniqueCount] = inputToken;
                tempAmounts[uniqueCount] = inputAmount;
                uniqueCount++;
            }
        }

        // Resize arrays using assembly (no copy needed)
        assembly {
            mstore(tempTokens, uniqueCount)
            mstore(tempAmounts, uniqueCount)
        }

        return (tempTokens, tempAmounts);
    }
}","keccak256":"0x5e4baf892aa914ac0c71444331e386adc5449f5fe074c194dd457a72a6da5157","license":"MIT"},"contracts/aori/contracts/IAori.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

interface IAori {
    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                           STATUS                           */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    enum OrderStatus {
        Unknown, // Order not found
        Active, // Order deposited but not filled
        Filled, // Pending settlement
        Cancelled, // Order cancelled
        Settled // Order settled
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                             ORDER                          */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    struct Order {
        uint128 inputAmount;
        uint128 outputAmount;
        address inputToken;
        address outputToken;
        uint32 startTime;
        uint32 endTime;
        uint32 srcEid;
        uint32 dstEid;
        address offerer;
        address recipient;
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                            HOOKS                           */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    struct SrcHook {
        address hookAddress;
        address preferredToken;
        uint256 minPreferedTokenAmountOut;
        bytes instructions;
    }

    struct DstHook {
        address hookAddress;
        address preferredToken;
        bytes instructions;
        uint256 preferedDstInputAmount;
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                          SRC EVENTS                        */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    event Deposit(bytes32 indexed orderId, Order order);
    event Cancel(bytes32 indexed orderId);
    event Settle(bytes32 indexed orderId);
    event Withdraw(address indexed holder, address indexed token, uint256 amount);

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                    CHAIN MANAGEMENT EVENTS                  */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    event ChainSupported(uint32 indexed eid);
    event ChainRemoved(uint32 indexed eid);

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                          DST EVENTS                        */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    event Fill(bytes32 indexed orderId, Order order);

    /**
     * @notice Emitted when an order is cancelled from the destination chain
     * @dev Contains MessagingReceipt data for cross-chain tracking
     * @param orderId The hash of the cancelled order
     * @param guid The unique identifier of the LayerZero message
     * @param nonce The nonce of the LayerZero message
     * @param fee The fee paid for the LayerZero message
     */
    event CancelSent(bytes32 indexed orderId, bytes32 guid, uint64 nonce, uint256 fee);

    /**
     * @notice Emitted when orders are settled from the destination chain
     * @dev Contains MessagingReceipt data for cross-chain tracking
     * @param srcEid The source endpoint ID
     * @param filler The address of the filler
     * @param payload The settlement payload
     * @param guid The unique identifier of the LayerZero message
     * @param nonce The nonce of the LayerZero message
     * @param fee The fee paid for the LayerZero message
     */
    event SettleSent(uint32 indexed srcEid, address indexed filler, bytes payload, bytes32 guid, uint64 nonce, uint256 fee);

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                        SRC FUNCTIONS                       */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    function deposit(Order calldata order, bytes calldata signature) external;

    function deposit(
        Order calldata order,
        bytes calldata signature,
        SrcHook calldata data
    ) external;

    function depositNative(Order calldata order) external payable;

    function withdraw(address token, uint256 amount) external;

    function cancel(bytes32 orderId) external;

    event settlementFailed(bytes32 indexed orderId, uint32 expectedEid, uint32 submittedEid, string reason);


    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                        DST FUNCTIONS                       */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    function fill(Order calldata order) external payable;

    function fill(Order calldata order, DstHook calldata hook) external payable;

    function settle(uint32 srcEid, address filler, bytes calldata extraOptions) external payable;

    function cancel(
        bytes32 orderId,
        Order calldata orderToCancel,
        bytes calldata extraOptions
    ) external payable;

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                        UTILITY FUNCTIONS                   */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    function hash(Order calldata order) external pure returns (bytes32);

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                       VIEW FUNCTIONS                       */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    function getLockedBalances(address offerer, address token) external view returns (uint256);

    function getUnlockedBalances(address offerer, address token) external view returns (uint256);

    function quote(
        uint32 _dstEid,
        uint8 _msgType,
        bytes calldata _options,
        bool _payInLzToken,
        uint32 _srcEid,
        address _filler
    ) external view returns (uint256 fee);

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                        HOOK EVENTS                         */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /**
     * @notice Emitted when a source hook is executed during deposit
     * @param orderId The hash of the order being processed
     * @param preferredToken The token address that was received from the hook
     * @param amountReceived The amount of tokens received from hook execution
     */
    event SrcHookExecuted(bytes32 indexed orderId, address indexed preferredToken, uint256 amountReceived);

    /**
     * @notice Emitted when a destination hook is executed during fill
     * @param orderId The hash of the order being processed
     * @param preferredToken The token address that was converted by the hook
     * @param amountReceived The amount of output tokens received from hook execution
     */
    event DstHookExecuted(bytes32 indexed orderId, address indexed preferredToken, uint256 amountReceived);
}","keccak256":"0xc35b79ce1b3a6098b45d5889bdaabc23ad9b56d487e4336ed0f72ce3e35e3f3b","license":"MIT"}},"version":1}
